import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  // In production this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tid;
    req.userId = payload.sub;
    next();
  } catch (e) {
    res.status(401).json({ error: 'invalid token' });
  }
}

// Search endpoint with filtering
app.get('/api/v1/documents/search', extractTenant, async (req, res) => {
  const { q, category, sort_by, order } = req.query;

  // Build base query with tenant isolation
  let query = `SELECT id, title, category, created_at, owner_id 
               FROM documents 
               WHERE tenant_id = $1`;
  const params = [req.tenantId];
  let paramIdx = 2;

  // Full-text search
  if (q) {
    query += ` AND to_tsvector('english', title || ' ' || content) @@ plainto_tsquery('english', $${paramIdx})`;
    params.push(q);
    paramIdx++;
  }

  // Category filter
  if (category) {
    query += ` AND category = $${paramIdx}`;
    params.push(category);
    paramIdx++;
  }

  // Dynamic sort - THIS IS THE VULNERABILITY
  const allowedColumns = ['title', 'created_at', 'category'];
  const sortCol = sort_by || 'created_at';
  const sortOrder = (order || 'desc').toLowerCase();

  // Developer thought this was safe because they check allowedColumns
  // but the check has a flaw
  if (allowedColumns.includes(sortCol)) {
    query += ` ORDER BY ${sortCol} ${sortOrder}`;
  } else {
    query += ` ORDER BY created_at DESC`;
  }

  query += ' LIMIT 50';

  try {
    const result = await pool.query(query, params);
    res.json({ documents: result.rows, count: result.rows.length });
  } catch (e) {
    console.error('Search error:', e.message);
    res.status(500).json({ error: 'search failed' });
  }
});

// Document detail with access check
app.get('/api/v1/documents/:id', extractTenant, async (req, res) => {
  const docId = req.params.id;
  // Validate UUID format
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(docId)) {
    return res.status(400).json({ error: 'invalid document id' });
  }

  try {
    const result = await pool.query(
      'SELECT * FROM documents WHERE id = $1 AND tenant_id = $2',
      [docId, req.tenantId]
    );
    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'not found' });
    }
    res.json({ document: result.rows[0] });
  } catch (e) {
    res.status(500).json({ error: 'fetch failed' });
  }
});

// Audit log write (fire-and-forget)
app.post('/api/v1/audit', extractTenant, async (req, res) => {
  const { action, resource_id, metadata } = req.body;
  const sanitizedMeta = JSON.stringify(metadata || {}).substring(0, 1024);
  await pool.query(
    'INSERT INTO audit_log (tenant_id, user_id, action, resource_id, metadata, ts) VALUES ($1, $2, $3, $4, $5, NOW())',
    [req.tenantId, req.userId, action, resource_id, sanitizedMeta]
  );
  res.status(202).json({ status: 'accepted' });
});

app.listen(3000, () => console.log('Document service listening on :3000'));
